 * @path app/Apps/ProjectPortal/Http/Requests/ResetProjectAccountPasswordRequest.php
 * @project JS web-platform
 * @author JS
 * @created 2026
 * @description New password of a client account set by the administration - typed in, or
 *   generated by the API when empty (the same policy as a new account).
 * @dependencies ProjectAccountController::resetPassword()
 */

namespace App\Apps\ProjectPortal\Http\Requests;

use Illuminate\Foundation\Http\FormRequest;
use Illuminate\Validation\Rules\Password;

class ResetProjectAccountPasswordRequest extends FormRequest
{
    public function authorize(): bool { return true; }

    /**
     * @description Optional password: at least 10 characters with letters and digits.
     * @return array<string, mixed>
     */
    public function rules(): array
    {
        return [
            'password' => ['nullable', 'string', 'max:255', Password::min(10)->letters()->numbers()],
        ];
    }
}
